using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about a file. This is an offline method
    /// </summary>
    public Task<TdLib.TdApi.Objects.File> GetFileAsync(int fileId = default)
    {

           using var activity =  StartCallActivity("GetFileAsync", typeof(GetFile).FullName ?? "GetFileAsync");

           try
           {
             return client.GetFileAsync(fileId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
